/* hand-written; not generated. Databricks twin of dbt/models/tags/tag_index.sql: one row per */ /* (tag_key, tag_value, source) over every place a tag is seen. Whole snapshot, complete days only */ /* -- no 30 marker. 0.6/0.5 are filled in at export time */ /* from config/settings.yml. tag_workspace's and tag_entity's own chains (minus tag_entity's */ /* statement/billed_* parts, not needed here) are inlined below -- no ref() in direct mode. */ WITH billing_rows /* ============================================================================================= */ /* 1. billing_custom_tags -- any tag on a DBU-billed usage row, complete days only. */ /* ============================================================================================= */ AS (SELECT ROW_NUMBER() OVER () AS rid, workspace_id, usage_date, usage_quantity, custom_tags FROM "sysx"."billing"."usage" WHERE usage_unit = 'DBU' AND usage_date < CAST('2026-09-21' AS DATE) AND ingestion_date < CAST('2026-09-21' AS DATE)), billing_pairs AS (SELECT b.workspace_id, b.usage_date, b.usage_quantity, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM billing_rows AS b CROSS JOIN LATERAL (SELECT unnest(map_keys(b.custom_tags)) AS raw_key, unnest(map_values(b.custom_tags)) AS raw_value) AS x WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY b.rid, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), src_billing_custom_tags AS (SELECT tag_key, tag_value, 'billing_custom_tags' AS source, COUNT(*) AS object_count, COUNT(DISTINCT workspace_id) AS workspace_count, SUM(usage_quantity) AS dbus, MIN(usage_date) AS first_seen, MAX(usage_date) AS last_seen FROM billing_pairs GROUP BY tag_key, tag_value), wsh_billed /* ============================================================================================= */ /* 2. workspace_inferred -- the workspaces' current tags (shared _workspace_history.sql block), */ /* allocating rows only. */ /* ============================================================================================= */ /* hand-written; not generated. Databricks twin of dbt/models/tags/tag_workspace_history.sql, as CTEs */ /* only: tools/export_direct_results.py pastes it where a tags query says __WORKSPACE_HISTORY__, and */ /* that query reads ws_history -- one row per (workspace_id, tag_key, valid_from), the workspace's */ /* tag inferred per billed day from sysx.billing.usage.custom_tags. A run of days with one value */ /* is a version once it has held 3 days (to the next change, or to today); a shorter run stays in */ /* the version before it. The first version starts on the workspace's first billed day, so days */ /* before a tag first showed read '__untagged__'. valid_to is exclusive, NULL on the current row. */ AS (SELECT ROW_NUMBER() OVER () AS rid, u.workspace_id, u.usage_date, u.usage_quantity, u.custom_tags FROM "sysx"."billing"."usage" AS u WHERE u.usage_unit = 'DBU' AND NOT u.workspace_id IS NULL AND u.usage_date < CAST('2026-09-21' AS DATE) AND u.ingestion_date < CAST('2026-09-21' AS DATE) AND /* an Azure workspace tag reaches serverless usage as well as classic compute, and a usage */ /* policy's tags are the policy's, not the workspace's */ u.usage_metadata.budget_policy_id IS NULL AND u.usage_metadata.usage_policy_id IS NULL), wsh_day_totals AS (SELECT workspace_id, usage_date, SUM(usage_quantity) AS dbus_total FROM wsh_billed GROUP BY workspace_id, usage_date), wsh_pairs AS (/* one (row, normalised key) pair; when a map holds two spellings of one key, the */ /* alphabetically first raw key wins */ SELECT b.workspace_id, b.usage_date, b.usage_quantity, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM wsh_billed AS b CROSS JOIN LATERAL (SELECT unnest(map_keys(b.custom_tags)) AS raw_key, unnest(map_values(b.custom_tags)) AS raw_value) AS x WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY b.rid, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), wsh_day_values AS (SELECT workspace_id, tag_key, usage_date, tag_value, SUM(usage_quantity) AS dbus FROM wsh_pairs GROUP BY workspace_id, tag_key, usage_date, tag_value), wsh_day_top AS (SELECT workspace_id, tag_key, usage_date, tag_value, dbus, SUM(dbus) OVER (PARTITION BY workspace_id, tag_key, usage_date) AS dbus_tagged, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, usage_date ORDER BY dbus DESC, tag_value NULLS FIRST) AS rn FROM wsh_day_values), wsh_day_state AS (/* every billed day of the workspace for every key it ever carried */ SELECT k.workspace_id, k.tag_key, t.usage_date, CASE WHEN d.dbus_tagged IS NULL OR d.dbus_tagged / NULLIF(t.dbus_total, 0) < 0.5 OR t.dbus_total <= 0 THEN '__untagged__' WHEN d.dbus / NULLIF(d.dbus_tagged, 0) >= 0.6 THEN d.tag_value ELSE '__mixed__' END AS state FROM (SELECT DISTINCT workspace_id, tag_key FROM wsh_day_values) AS k JOIN wsh_day_totals AS t ON t.workspace_id = k.workspace_id LEFT JOIN wsh_day_top AS d ON d.workspace_id = k.workspace_id AND d.tag_key = k.tag_key AND d.usage_date = t.usage_date AND d.rn = 1), wsh_runs AS (SELECT workspace_id, tag_key, state, MIN(usage_date) AS run_from FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key ORDER BY usage_date NULLS FIRST) - ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, state ORDER BY usage_date NULLS FIRST) AS grp FROM wsh_day_state) AS d GROUP BY workspace_id, tag_key, state, grp), wsh_kept AS (/* a run stands once it has held 3 days, counted to the next run or to today */ SELECT *, CASE WHEN DATE_DIFF('DAY', run_from, COALESCE(LEAD(run_from) OVER (PARTITION BY workspace_id, tag_key ORDER BY run_from NULLS FIRST), CAST('2026-09-21' AS DATE))) >= 3 THEN state END AS kept_state FROM wsh_runs), wsh_smoothed AS (/* a short run takes the value of the last run that stands before it; a short first run keeps its own */ SELECT workspace_id, tag_key, run_from, COALESCE(kept_state, LAST_VALUE(kept_state IGNORE NULLS) OVER (PARTITION BY workspace_id, tag_key ORDER BY run_from NULLS FIRST ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), state) AS state FROM wsh_kept), wsh_versions AS (SELECT workspace_id, tag_key, state AS tag_value, MIN(run_from) AS valid_from FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key ORDER BY run_from NULLS FIRST) - ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, state ORDER BY run_from NULLS FIRST) AS grp FROM wsh_smoothed) AS s GROUP BY workspace_id, tag_key, state, grp), wsh_dated AS (SELECT *, LEAD(valid_from) OVER (PARTITION BY workspace_id, tag_key ORDER BY valid_from NULLS FIRST) AS valid_to FROM wsh_versions), wsh_version_values AS (SELECT v.workspace_id, v.tag_key, v.valid_from, d.tag_value, SUM(d.dbus) AS dbus FROM wsh_dated AS v JOIN wsh_day_values AS d ON d.workspace_id = v.workspace_id AND d.tag_key = v.tag_key AND d.usage_date >= v.valid_from AND (v.valid_to IS NULL OR d.usage_date < v.valid_to) GROUP BY v.workspace_id, v.tag_key, v.valid_from, d.tag_value), wsh_version_ranked AS (SELECT *, SUM(dbus) OVER (PARTITION BY workspace_id, tag_key, valid_from) AS dbus_tagged, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, valid_from ORDER BY dbus DESC, tag_value NULLS FIRST) AS rn FROM wsh_version_values), wsh_top_values AS (SELECT workspace_id, tag_key, valid_from, LIST_TRANSFORM(ARRAY_SORT(ARRAY_AGG({'rn': rn, 'v': tag_value}) FILTER(WHERE {'rn': rn, 'v': tag_value} IS NOT NULL)), x -> x.v) AS top_values FROM wsh_version_ranked WHERE rn <= 5 GROUP BY workspace_id, tag_key, valid_from), wsh_version_totals AS (SELECT v.workspace_id, v.tag_key, v.valid_from, SUM(t.dbus_total) AS dbus_total FROM wsh_dated AS v JOIN wsh_day_totals AS t ON t.workspace_id = v.workspace_id AND t.usage_date >= v.valid_from AND (v.valid_to IS NULL OR t.usage_date < v.valid_to) GROUP BY v.workspace_id, v.tag_key, v.valid_from), wsh_display AS (/* the raw spelling carrying the most DBUs account-wide names the key on screen */ SELECT tag_key, raw_key AS display_key FROM (SELECT tag_key, raw_key, ROW_NUMBER() OVER (PARTITION BY tag_key ORDER BY SUM(usage_quantity) DESC, raw_key NULLS FIRST) AS rn FROM wsh_pairs GROUP BY tag_key, raw_key) AS d WHERE rn = 1), wsh_measured AS (SELECT v.workspace_id, v.tag_key, d.display_key, v.tag_value, v.valid_from, v.valid_to, r.tag_value AS top_value, tv.top_values, r.dbus / NULLIF(r.dbus_tagged, 0) AS share, COALESCE(r.dbus_tagged, 0) / NULLIF(t.dbus_total, 0) AS coverage, COALESCE(r.dbus_tagged, 0) AS dbus_tagged, t.dbus_total, CASE WHEN v.valid_to IS NULL THEN 'since ' || CAST(v.valid_from AS TEXT) ELSE 'from ' || CAST(v.valid_from AS TEXT) || ' to ' || CAST(CAST(v.valid_to AS DATE) + INTERVAL (1 * -1) DAY AS TEXT) END AS period FROM wsh_dated AS v JOIN wsh_version_totals AS t ON t.workspace_id = v.workspace_id AND t.tag_key = v.tag_key AND t.valid_from = v.valid_from JOIN wsh_display AS d ON d.tag_key = v.tag_key LEFT JOIN wsh_version_ranked AS r ON r.workspace_id = v.workspace_id AND r.tag_key = v.tag_key AND r.valid_from = v.valid_from AND r.rn = 1 LEFT JOIN wsh_top_values AS tv ON tv.workspace_id = v.workspace_id AND tv.tag_key = v.tag_key AND tv.valid_from = v.valid_from), ws_history AS (SELECT workspace_id, tag_key, display_key, tag_value, NOT tag_value IN ('__mixed__', '__untagged__') AS is_allocating, valid_from, valid_to, valid_to IS NULL AS is_current, top_value, top_values, share, coverage, dbus_tagged, dbus_total, CASE WHEN top_value IS NULL THEN period || ': no billed usage of this workspace carries ' || display_key WHEN tag_value = '__untagged__' THEN period || ': only ' || CAST(ROUND(COALESCE(coverage, 0) * 100, 1) AS TEXT) || '% of this workspace''s billed DBUs carry ' || display_key || ' (top value "' || top_value || '"); at least 50.0% is needed to infer a workspace tag' WHEN tag_value = '__mixed__' THEN period || ': no single ' || display_key || ' value reaches 60.0% of the ' || display_key || '-tagged DBUs (top "' || top_value || '" at ' || CAST(ROUND(share * 100, 1) AS TEXT) || '%); tagged DBUs are ' || CAST(ROUND(coverage * 100, 1) AS TEXT) || '% of this workspace''s billed DBUs' ELSE period || ': ' || display_key || ' "' || tag_value || '" carries ' || CAST(ROUND(share * 100, 1) AS TEXT) || '% of the ' || display_key || '-tagged DBUs, which are ' || CAST(ROUND(coverage * 100, 1) AS TEXT) || '% of this workspace''s billed DBUs' END AS reason FROM wsh_measured), tag_workspace AS (SELECT workspace_id, tag_key, tag_value, display_key, is_allocating, share, dbus_tagged FROM ws_history WHERE is_current), src_workspace_inferred AS (SELECT tag_key, tag_value, 'workspace_inferred' AS source, COUNT(DISTINCT workspace_id) AS object_count, COUNT(DISTINCT workspace_id) AS workspace_count, SUM(share * dbus_tagged) AS dbus, CAST(NULL AS DATE) AS first_seen, CAST(NULL AS DATE) AS last_seen FROM tag_workspace WHERE is_allocating GROUP BY tag_key, tag_value), warehouse_latest /* ============================================================================================= */ /* 3. Resource / job / pipeline tags -- tag_entity's latest-SCD2 rows, inlined. */ /* ============================================================================================= */ AS (SELECT warehouse_id, workspace_id, tags, ROW_NUMBER() OVER (PARTITION BY warehouse_id ORDER BY change_time DESC) AS rn FROM "sysx"."compute"."warehouses"), warehouse_pairs AS (SELECT w.warehouse_id AS entity_id, w.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value, 'warehouse_tags' AS source FROM warehouse_latest AS w CROSS JOIN LATERAL (SELECT unnest(map_keys(w.tags)) AS raw_key, unnest(map_values(w.tags)) AS raw_value) AS x WHERE w.rn = 1 AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY w.warehouse_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), pool_latest AS (SELECT instance_pool_id, workspace_id, tags, ROW_NUMBER() OVER (PARTITION BY instance_pool_id ORDER BY change_time DESC) AS rn FROM "sysx"."compute"."instance_pools"), pool_pairs AS (SELECT p.instance_pool_id, p.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM pool_latest AS p CROSS JOIN LATERAL (SELECT unnest(map_keys(p.tags)) AS raw_key, unnest(map_values(p.tags)) AS raw_value) AS x WHERE p.rn = 1 AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY p.instance_pool_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), pool_entity_pairs AS (SELECT instance_pool_id AS entity_id, workspace_id, raw_key, tag_key, tag_value, 'pool_tags' AS source FROM pool_pairs), cluster_latest AS (SELECT cluster_id, workspace_id, tags, worker_instance_pool_id, driver_instance_pool_id, ROW_NUMBER() OVER (PARTITION BY cluster_id ORDER BY change_time DESC) AS rn FROM "sysx"."compute"."clusters"), cluster_own_pairs AS (SELECT c.cluster_id, c.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM cluster_latest AS c CROSS JOIN LATERAL (SELECT unnest(map_keys(c.tags)) AS raw_key, unnest(map_values(c.tags)) AS raw_value) AS x WHERE c.rn = 1 AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY c.cluster_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), cluster_pool_fallback AS (SELECT c.cluster_id, c.workspace_id, wp.raw_key, wp.tag_key, wp.tag_value FROM cluster_latest AS c JOIN pool_pairs AS wp ON wp.instance_pool_id = c.worker_instance_pool_id WHERE c.rn = 1 AND NOT c.worker_instance_pool_id IS NULL UNION ALL SELECT c.cluster_id, c.workspace_id, dp.raw_key, dp.tag_key, dp.tag_value FROM cluster_latest AS c JOIN pool_pairs AS dp ON dp.instance_pool_id = c.driver_instance_pool_id WHERE c.rn = 1 AND NOT c.driver_instance_pool_id IS NULL AND NOT EXISTS(SELECT 1 FROM pool_pairs AS wp2 WHERE wp2.instance_pool_id = c.worker_instance_pool_id AND wp2.tag_key = dp.tag_key)), cluster_pool_fallback_unclaimed AS (SELECT f.cluster_id, f.workspace_id, f.raw_key, f.tag_key, f.tag_value FROM cluster_pool_fallback AS f WHERE NOT EXISTS(SELECT 1 FROM cluster_own_pairs AS o WHERE o.cluster_id = f.cluster_id AND o.tag_key = f.tag_key)), resource_entity AS (SELECT entity_id, workspace_id, raw_key, tag_key, tag_value, source FROM warehouse_pairs UNION ALL SELECT entity_id, workspace_id, raw_key, tag_key, tag_value, source FROM pool_entity_pairs UNION ALL SELECT cluster_id, workspace_id, raw_key, tag_key, tag_value, 'cluster_tags' FROM cluster_own_pairs UNION ALL SELECT cluster_id, workspace_id, raw_key, tag_key, tag_value, 'pool_tags' FROM cluster_pool_fallback_unclaimed UNION ALL SELECT job_id, workspace_id, raw_key, tag_key, tag_value, 'job_tags' FROM (SELECT j.job_id, j.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM (SELECT job_id, workspace_id, tags, ROW_NUMBER() OVER (PARTITION BY workspace_id, job_id ORDER BY change_time DESC) AS rn FROM "sysx"."lakeflow"."jobs") AS j CROSS JOIN LATERAL (SELECT unnest(map_keys(j.tags)) AS raw_key, unnest(map_values(j.tags)) AS raw_value) AS x WHERE j.rn = 1 AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY j.workspace_id, j.job_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1) UNION ALL SELECT pipeline_id, workspace_id, raw_key, tag_key, tag_value, 'pipeline_tags' FROM (SELECT p.pipeline_id, p.workspace_id, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM (SELECT pipeline_id, workspace_id, tags, ROW_NUMBER() OVER (PARTITION BY workspace_id, pipeline_id ORDER BY change_time DESC) AS rn FROM "sysx"."lakeflow"."pipelines") AS p CROSS JOIN LATERAL (SELECT unnest(map_keys(p.tags)) AS raw_key, unnest(map_values(p.tags)) AS raw_value) AS x WHERE p.rn = 1 AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY p.workspace_id, p.pipeline_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1)), src_resource_tags AS (SELECT tag_key, tag_value, source, COUNT(DISTINCT entity_id || '~' || COALESCE(workspace_id, '~')) AS object_count, COUNT(DISTINCT workspace_id) AS workspace_count, CAST(NULL AS DOUBLE) AS dbus, CAST(NULL AS DATE) AS first_seen, CAST(NULL AS DATE) AS last_seen FROM resource_entity GROUP BY tag_key, tag_value, source), query_pairs /* ============================================================================================= */ /* 4a. query_tags -- sysx.query.history, whole snapshot. */ /* ============================================================================================= */ AS (SELECT q.workspace_id, q.statement_id, CAST(q.start_time AS DATE) AS stmt_date, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM "sysx"."query"."history" AS q CROSS JOIN LATERAL (SELECT unnest(map_keys(q.query_tags)) AS raw_key, unnest(map_values(q.query_tags)) AS raw_value) AS x WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY q.statement_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), src_query_tags AS (SELECT tag_key, tag_value, 'query_tags' AS source, COUNT(DISTINCT statement_id || '~' || COALESCE(workspace_id, '~')) AS object_count, COUNT(DISTINCT workspace_id) AS workspace_count, CAST(NULL AS DOUBLE) AS dbus, MIN(stmt_date) AS first_seen, MAX(stmt_date) AS last_seen FROM query_pairs GROUP BY tag_key, tag_value), attributed_pairs /* ============================================================================================= */ /* 4b. attributed_query_tags -- billing.attributed_usage.granular_tags.query_tags. */ /* ============================================================================================= */ AS (SELECT a.workspace_id, a.record_id, a.usage_date, a.active_usage_quantity, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM "sysx"."billing"."attributed_usage" AS a CROSS JOIN UNNEST(a.granular_tags.query_tags) AS x(raw_key, raw_value) WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY a.record_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), src_attributed_query_tags AS (SELECT tag_key, tag_value, 'attributed_query_tags' AS source, COUNT(DISTINCT record_id) AS object_count, COUNT(DISTINCT workspace_id) AS workspace_count, SUM(active_usage_quantity) AS dbus, MIN(usage_date) AS first_seen, MAX(usage_date) AS last_seen FROM attributed_pairs GROUP BY tag_key, tag_value), uc_entity /* ============================================================================================= */ /* 5. Unity Catalog tags -- already flat rows, no map to explode. workspace_count is always NULL. */ /* ============================================================================================= */ AS (SELECT LOWER(t.catalog_name) || '.' || LOWER(t.schema_name) || '.' || LOWER(t.table_name) AS entity_id, t.tag_name AS raw_key, REGEXP_REPLACE(LOWER(t.tag_name), '[ _-]+', '', 'g') AS tag_key, TRIM(t.tag_value) AS tag_value, 'uc_table_tags' AS source FROM "sysx"."information_schema"."table_tags" AS t WHERE NOT t.tag_name IS NULL AND NOT t.tag_value IS NULL AND REGEXP_REPLACE(LOWER(t.tag_name), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(t.catalog_name), LOWER(t.schema_name), LOWER(t.table_name), REGEXP_REPLACE(LOWER(t.tag_name), '[ _-]+', '', 'g') ORDER BY t.tag_name NULLS FIRST) = 1 UNION ALL SELECT LOWER(s.catalog_name) || '.' || LOWER(s.schema_name) AS entity_id, s.tag_name AS raw_key, REGEXP_REPLACE(LOWER(s.tag_name), '[ _-]+', '', 'g') AS tag_key, TRIM(s.tag_value) AS tag_value, 'uc_schema_tags' AS source FROM "sysx"."information_schema"."schema_tags" AS s WHERE NOT s.tag_name IS NULL AND NOT s.tag_value IS NULL AND REGEXP_REPLACE(LOWER(s.tag_name), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(s.catalog_name), LOWER(s.schema_name), REGEXP_REPLACE(LOWER(s.tag_name), '[ _-]+', '', 'g') ORDER BY s.tag_name NULLS FIRST) = 1 UNION ALL SELECT LOWER(c.catalog_name) || '.' || LOWER(c.schema_name) || '.' || LOWER(c.table_name) || '.' || LOWER(c.column_name) AS entity_id, c.tag_name AS raw_key, REGEXP_REPLACE(LOWER(c.tag_name), '[ _-]+', '', 'g') AS tag_key, TRIM(c.tag_value) AS tag_value, 'uc_column_tags' AS source FROM "sysx"."information_schema"."column_tags" AS c WHERE NOT c.tag_name IS NULL AND NOT c.tag_value IS NULL AND REGEXP_REPLACE(LOWER(c.tag_name), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(c.catalog_name), LOWER(c.schema_name), LOWER(c.table_name), LOWER(c.column_name), REGEXP_REPLACE(LOWER(c.tag_name), '[ _-]+', '', 'g') ORDER BY c.tag_name NULLS FIRST) = 1 UNION ALL SELECT LOWER(v.catalog_name) || '.' || LOWER(v.schema_name) || '.' || LOWER(v.volume_name) AS entity_id, v.tag_name AS raw_key, REGEXP_REPLACE(LOWER(v.tag_name), '[ _-]+', '', 'g') AS tag_key, TRIM(v.tag_value) AS tag_value, 'uc_volume_tags' AS source FROM "sysx"."information_schema"."volume_tags" AS v WHERE NOT v.tag_name IS NULL AND NOT v.tag_value IS NULL AND REGEXP_REPLACE(LOWER(v.tag_name), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(v.catalog_name), LOWER(v.schema_name), LOWER(v.volume_name), REGEXP_REPLACE(LOWER(v.tag_name), '[ _-]+', '', 'g') ORDER BY v.tag_name NULLS FIRST) = 1), src_uc_tags AS (SELECT tag_key, tag_value, source, COUNT(DISTINCT entity_id) AS object_count, CAST(NULL AS BIGINT) AS workspace_count, CAST(NULL AS DOUBLE) AS dbus, CAST(NULL AS DATE) AS first_seen, CAST(NULL AS DATE) AS last_seen FROM uc_entity GROUP BY tag_key, tag_value, source), ai_gateway_pairs /* ============================================================================================= */ /* 6. ai_gateway_endpoint_tags -- sysx.ai_gateway.usage.endpoint_tags, per gateway request. */ /* ============================================================================================= */ AS (SELECT g.workspace_id, g.request_id, COALESCE(g.endpoint_id, g.endpoint_name) AS ep_id, CAST(g.event_time AS DATE) AS ev_date, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM "sysx"."ai_gateway"."usage" AS g CROSS JOIN LATERAL (SELECT unnest(map_keys(g.endpoint_tags)) AS raw_key, unnest(map_values(g.endpoint_tags)) AS raw_value) AS x WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY g.request_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), src_ai_gateway_endpoint_tags AS (SELECT tag_key, tag_value, 'ai_gateway_endpoint_tags' AS source, COUNT(DISTINCT ep_id || '~' || COALESCE(workspace_id, '~')) AS object_count, COUNT(DISTINCT workspace_id) AS workspace_count, CAST(NULL AS DOUBLE) AS dbus, MIN(ev_date) AS first_seen, MAX(ev_date) AS last_seen FROM ai_gateway_pairs GROUP BY tag_key, tag_value), all_raw_pairs /* ============================================================================================= */ /* display_key / raw_keys: over every source's raw spellings (most object_count wins, ties */ /* alphabetical); raw_keys is the sorted list, capped at 10. */ /* ============================================================================================= */ AS (SELECT tag_key, raw_key FROM billing_pairs UNION ALL SELECT tag_key, display_key AS raw_key FROM tag_workspace WHERE is_allocating UNION ALL SELECT tag_key, raw_key FROM resource_entity UNION ALL SELECT tag_key, raw_key FROM query_pairs UNION ALL SELECT tag_key, raw_key FROM attributed_pairs UNION ALL SELECT tag_key, raw_key FROM uc_entity UNION ALL SELECT tag_key, raw_key FROM ai_gateway_pairs), raw_key_counts AS (SELECT tag_key, raw_key, COUNT(*) AS n FROM all_raw_pairs GROUP BY tag_key, raw_key), key_display AS (SELECT tag_key, raw_key AS display_key FROM (SELECT tag_key, raw_key, ROW_NUMBER() OVER (PARTITION BY tag_key ORDER BY n DESC, raw_key NULLS FIRST) AS rn FROM raw_key_counts) AS ranked WHERE rn = 1), raw_key_distinct_ranked AS (SELECT tag_key, raw_key, ROW_NUMBER() OVER (PARTITION BY tag_key ORDER BY raw_key NULLS FIRST) AS rn FROM (SELECT DISTINCT tag_key, raw_key FROM all_raw_pairs)), key_raw_keys AS (SELECT tag_key, ARRAY_TO_STRING(LIST_SORT(LIST(DISTINCT raw_key) FILTER(WHERE NOT raw_key IS NULL)), ',') AS raw_keys FROM raw_key_distinct_ranked WHERE rn <= 10 GROUP BY tag_key), all_final /* ============================================================================================= */ /* Every source's (tag_key, tag_value, source) rows, unioned (this is the model's own grain). */ /* ============================================================================================= */ AS (SELECT * FROM src_billing_custom_tags UNION ALL SELECT * FROM src_workspace_inferred UNION ALL SELECT * FROM src_resource_tags UNION ALL SELECT * FROM src_query_tags UNION ALL SELECT * FROM src_attributed_query_tags UNION ALL SELECT * FROM src_uc_tags UNION ALL SELECT * FROM src_ai_gateway_endpoint_tags) SELECT f.tag_key, kd.display_key, kr.raw_keys, f.tag_value, f.source, f.object_count, f.workspace_count, f.dbus, f.first_seen, f.last_seen FROM all_final AS f LEFT JOIN key_display AS kd ON kd.tag_key = f.tag_key LEFT JOIN key_raw_keys AS kr ON kr.tag_key = f.tag_key